INSERT INTO `banners` (`id`, `title`, `description`, `image_url`, `link_url`, `sort_order`, `is_active`, `create_time`, `update_time`, `is_deleted`) VALUES (4,'Java+AI应用开发','以Java+大模型应用为核，广度延伸至大数据&人工智能！','https://picsum.photos/id/24/400/300','https://picsum.photos/id/24/400/300',1,1,'2026-04-25 10:27:00','2026-05-15 02:00:49',1),(5,'嵌入式&万物互联','大牛手把手教你实操企业真实项目，无缝对接企业真实工作流程','https://stone-ai-exam.oss-cn-hangzhou.aliyuncs.com/stone/banners/2026/06/6a1fcc21ceed28d0db69d183.jpg','https://picsum.photos/id/42/400/300',2,1,'2026-04-25 10:27:00','2026-06-03 06:39:31',0),(6,'人工智能大模型','全球人工智能浪潮正劲，时代红利，先到先得！','https://stone-ai-exam.oss-cn-hangzhou.aliyuncs.com/stone/banners/2026/05/6a0883f77c59429f8cbf7719.jpg','https://www.bilibili.com/video/BV13U4y1N7Uo',3,1,'2026-04-25 10:27:00','2026-05-17 01:51:13',0),(7,'AI智能运维','BAT级实战课研团队,直面百亿级业务运维现场！','https://picsum.photos/id/20/400/300','https://picsum.photos/id/20/400/300',4,1,'2026-04-26 07:36:37','2026-05-16 15:06:12',0),(8,'智能考试系统介绍','基于AI技术的智能考试平台，支持在线考试、智能组卷等功能','https://stone-ai-exam.oss-cn-hangzhou.aliyuncs.com/stone/banners/2026/06/6a1fd32eceed28d0db69d184.jpg','https://picsum.photos/400/300',1,1,'2026-04-24 08:42:53','2026-06-03 07:09:36',0),(9,'测试轮播图','测试轮播图描述','https://stone-ai-exam.oss-cn-hangzhou.aliyuncs.com/stone/banners/2026/05/6a0883b87c59429f8cbf7717.jpg','https://www.bilibili.com/video/BV1CAxaeHEeH',2,1,'2026-04-24 08:55:46','2026-05-17 01:41:35',0),(10,'测试轮播图','测试轮播图','https://stone-ai-exam.oss-cn-hangzhou.aliyuncs.com/stone/banners/2026/05/6a0726c57c59629e243fbb2a.jpg','https://www.baidu.com',5,1,'2026-05-15 13:59:38','2026-05-15 14:13:57',0);
