INSERT INTO `exam_records` (`id`, `exam_id`, `student_name`, `score`, `summary`, `start_time`, `end_time`, `status`, `window_switches`, `create_time`, `update_time`, `is_deleted`) VALUES (38,15,'张楚岚',0,NULL,'2026-04-30 07:18:44',NULL,'进行中',0,'2026-04-30 07:18:43','2026-06-02 12:00:28',0),(39,17,'xxx',0,NULL,'2026-04-30 08:32:25',NULL,'进行中',0,'2026-04-30 08:32:25','2026-04-30 08:32:25',0),(40,20,'Jackson',0,NULL,'2026-04-30 08:47:43',NULL,'进行中',0,'2026-04-30 08:47:43','2026-06-02 12:01:09',0),(41,20,'测试',10,'本次考试成绩显示，学生在理解和掌握课程内容方面存在较大差距。得分率仅为16.7%，反映出学生对知识点的掌握不全面，解题技巧和应用能力亟待提高。优势在于能够答对两道题目，显示出一定的基础理解能力。不足之处在于多数题目未能正确解答，需要加强知识点的深入理解和运用。建议学生从基础知识入手，加强概念理解，多做练习题，提高解题速度和准确度。同时，注重培养逻辑思维和分析问题的能力。保持积极态度，相信自己能够通过努力提高成绩。加油，你有能力做得更好！','2026-04-30 10:54:51','2026-04-30 10:55:11','已批阅',0,'2026-04-30 10:54:51','2026-06-03 05:58:04',1),(42,9,'sss',0,NULL,'2026-05-31 05:26:19',NULL,'进行中',0,'2026-05-31 05:26:18','2026-05-31 05:26:18',0),(43,24,'Stone',34,'Stone同学，这次“智能组卷002”测试得分率48.6%，反映出基础存在不少漏洞，但12题中答对6题，也说明你已掌握部分知识点，并非从零开始。你的优势在于有一定的解题直觉，能拿下半数题目；不足之处是知识体系不牢固，综合运用和审题能力偏弱，导致失分较多。建议你按错题追溯到具体知识模块，先补概念再练典型题型，建立错题本反复巩固，并限时训练提升准确率。每一次暴露问题都是进步的阶梯，稳住心态，扎实前行，你一定能把得分率提上来！','2026-05-31 05:28:43','2026-06-01 02:41:38','已批阅',0,'2026-05-31 05:28:42','2026-06-02 08:25:36',1),(44,15,'Stone',0,NULL,'2026-05-31 05:32:34',NULL,'进行中',0,'2026-05-31 05:32:36','2026-05-31 05:32:36',0),(45,24,'Stone',39,'Stone同学，本次智能组卷002的检测反映出你已掌握一定基础，正确率刚过半，说明知识框架初步形成，这是值得肯定的起点。但目前得分率55.7%也清晰显示，你对超过四成的考点理解尚不透彻，知识体系存在明显断层，尤其在综合运用和变通题型上较薄弱。建议你不要满足于“听懂”，而要建立错题溯源的习惯，逐题深究错因，回到课本或笔记把关联知识点重新梳理，再辅以同类变式练习巩固，做到举一反三。学习如攀峰，半山最费力，但只要方向对、步子实，每一次纠错都在为你登顶蓄力。沉下心，把漏洞一个个补上，你完全可以实现大跨步的提升！','2026-06-01 02:43:16','2026-06-01 02:46:52','已批阅',0,'2026-06-01 02:43:15','2026-06-01 02:43:15',0),(46,24,'Stone',30,'Stone同学，这次“智能组卷002”的成绩反映出你目前的基础还不够扎实，42.9%的得分率说明知识漏洞比较明显，但也看到你做对的6道题展现了一定的理解力。你的优势在于部分知识点掌握尚可，能拿到基础分；不足之处是整体解题的准确率和知识系统性偏弱，遇到综合题型容易失分。建议你稳住心态，从错题入手，逐道分析失分原因，按单元梳理核心概念，先夯实基础再适度练综合题。每天坚持半小时针对性训练，你会看到稳步提升。别气馁，爬坡的路上每一步都算数，继续加油！','2026-06-01 02:58:21','2026-06-01 02:59:26','已批阅',0,'2026-06-01 02:58:21','2026-06-01 02:58:21',0),(47,24,'Lin',46,'Lin同学，本次智能组卷002得分46分（满分70分），正确率约65.7%，整体表现处于中等偏上水平。你答对了7道题，说明基础知识点掌握尚可，但仍有近三分之一的失分，反映出在某些模块存在知识盲区或解题不够严谨。优势在于能拿下多数基础题，失分可能集中在综合应用或易混淆概念上。建议尽快复盘错题，归纳错因是知识疏漏还是审题不清，并针对性做同类题强化，构建完整的知识网络。学习如登山，每一步复盘都在拔高自己，稳住节奏，你完全有能力突破70分的大关，继续加油！','2026-06-01 03:35:54','2026-06-01 03:37:48','已批阅',0,'2026-06-01 03:35:53','2026-06-01 03:35:53',0),(48,24,'Link',55,'Link同学，本次智能组卷002考试你取得55分（得分率78.6%），整体表现良好，说明基础知识掌握较为扎实，解题正确率达到三分之二以上，值得肯定。\n\n从数据看，答对8道、答错4道，优势在于你能稳定发挥，拿下大部分中等难度题目；但短板也很明显——面对综合性或变式题时，准确率有所下降，可能存在审题疏漏、概念理解不够深入或解题思路固化等问题。\n\n建议接下来重点做好三件事：一是建立错题档案，将本次4道错题按“知识性错误”“逻辑性错误”“习惯性错误”分类归因，逐道重做并口述思路；二是对失分章节进行限时专项训练，刻意练习提取关键信息的准确度；三是每周做一套综合卷，模拟考试节奏，培养检查习惯，减少无谓丢分。\n\n78.6%是你现阶段真实的坐标，也是扎实起步的证明。保持节奏，稳住心态，把漏洞补上，下一次一定能突破瓶颈。加油！','2026-06-01 16:03:29','2026-06-01 16:05:09','已批阅',0,'2026-06-01 16:03:29','2026-06-01 16:03:29',0),(49,24,'Jackson',47,'Jackson同学，本次智能组卷002的考试总得分47分（满分70），得分率67.1%，整体表现处于基础巩固阶段。你答对了7道题，展现了稳定的知识掌握和不错的答题准确度，尤其在已掌握的知识点上思路清晰。主要不足在于对部分中高难度考点理解不够透彻，存在知识盲区，导致失分较集中。建议你重点梳理错题题型，建立专项错题本，针对薄弱知识点进行限时强化训练，并尝试用思维导图串联概念间的联系。别灰心，每一步扎实的努力都会转化为进步的阶梯，相信下次你一定能突破瓶颈，继续加油！','2026-06-03 04:23:58','2026-06-03 04:25:25','已批阅',0,'2026-06-03 04:23:57','2026-06-03 04:23:57',0),(50,9,'sfssf',0,'sfssf同学，你好。本次测试成绩确实不理想，0分的结果反映出当前知识掌握与考试要求之间存在明显断层。但请不要气馁，这恰恰为我们提供了最清晰的起点。优势在于，你至少完整参与了这次测试，呈现出的是真实的基础状态，让问题暴露无遗。不足是全方位的，可能涉及知识点未理解、审题不清或完全无从下手。建议你立即回归课本，从最基础的例题入手，哪怕每天只彻底弄懂一道题，也要保证真正吸收。同时，建立错题本，记录每一个卡住你的步骤，主动向老师或同学请教。失败不是终点，而是校准方向的契机，只要你肯把步子放慢、踩实，每一次微小的进步都算数。加油，从零开始也能筑起高楼。','2026-06-03 14:12:28','2026-06-03 14:12:32','已批阅',0,'2026-06-03 14:12:28','2026-06-03 14:12:28',0),(51,24,'Batrits',47,'Batrits同学，本次智能组卷002考试总得分47分（得分率67.1%），答对8道题，整体表现达到良好水平，说明你对大部分知识点有较好的掌握，基础较为扎实。你的优势在于能够稳定解决多数常规题型，展现了一定的思维严谨性；但不足之处也较明显，约有三分之一的题目失分，可能反映出在综合应用能力、易混淆概念的辨析或审题细致度上仍存短板。建议你针对错题进行深度复盘，回归对应的知识模块，梳理出易错点和薄弱环节，并有意识地加强综合性题目的训练，提升知识的灵活迁移能力。同时养成逐字审题、验算复盘的习惯，避免非智力因素丢分。相信凭借你的认真态度和潜力，只要针对性地补强，下一次一定能突破自己，取得更优异的成绩，继续加油！','2026-06-03 15:06:41','2026-06-03 15:07:52','已批阅',0,'2026-06-03 15:06:41','2026-06-03 15:06:41',0),(52,9,'Batrits',53,'Batrits同学，这次测试总分53分（得分率58.9%），说明你已掌握一部分基础知识，但整体尚处于爬坡阶段。值得肯定的是，你在18题中答对了10题，表现出一定的理解力和解题勇气。主要不足在于知识碎片化，缺乏系统整合，审题和解题思路易中断，导致失误增多。建议你做好三点：一是梳理错题，归类错误类型，针对性补漏；二是重视教材，用思维导图把零散点连成网；三是限时训练，培养审题与检查习惯。进步从来不是一蹴而就，请你相信持续努力的意义，你完全有能力突破及格线并向更高目标迈进，加油！','2026-06-03 16:07:03','2026-06-04 08:52:40','已批阅',0,'2026-06-03 16:07:02','2026-06-03 16:07:02',0),(53,9,'hanli',44,'hanli同学，你在“测试001”中得分44分（满分90分），得分率48.9%，18题答对8题。整体来看，基础知识还有较大提升空间，但能够答对近半题目，说明已具备一定理解。你的优势在于不是零基础，部分知识点掌握尚可；不足在于知识体系不够完整，解题准确率和熟练度有待提高，可能存在审题不清或概念混淆。建议你从错题入手，回归课本，建立错题本，把每道错题对应的知识点学透，并找同类题巩固，定期复习。学习如登山，每一步都算数。别因一次成绩气馁，找准薄弱点，踏实改进，你一定能稳步提升。加油！','2026-06-04 06:16:26','2026-06-04 06:18:48','已批阅',0,'2026-06-04 06:16:26','2026-06-04 06:16:26',0),(54,9,'Batrits',48,'Batrits同学，本次测试成绩反映出你已具备一定的知识基础，能答对一半题目说明基本概念有掌握。但53.3%的得分率也暴露出知识体系存在明显断层，尤其在综合应用和难点突破上还需加强。你的优势在于部分模块掌握较扎实，不足在于解题完整性和准确性欠佳，容易在细节或变式题上失分。建议立即整理错题本，逐题分析错误根源，针对薄弱知识点进行专项练习，每周至少完成一次限时自测。别忘了，分数只是成长的刻度，而非定义你的标签。带着反思持续努力，你一定能实现突破，下一次定会看到更好的自己！','2026-06-04 08:53:46','2026-06-04 08:54:37','已批阅',0,'2026-06-04 08:53:45','2026-06-04 08:53:45',0),(55,24,'Batrits',42,'Batrits同学，本次智能组卷002考试总得分42分（满分70分），得分率60%，处于刚刚达标的水平。你答对了半数以上题目，说明具备一定的知识基础，能应对常规考查，值得肯定。但失分题集中在近四成，反映出知识体系仍有薄弱环节，如重点概念理解不透彻、综合运用能力不足或审题不够细致。建议你仔细复盘错题，将错因归类（知识遗忘、理解偏差、技巧缺失），针对弱项模块进行专题强化，并结合变式题训练，提升迁移应用能力。学习过程中注意定期小结，构建知识网络，避免零散记忆。60%不是终点，而是精准发力的新起点，找到症结、扎实补漏，你完全有能力冲上更高分段，加油！','2026-06-04 08:57:22','2026-06-04 08:57:50','已批阅',0,'2026-06-04 08:57:22','2026-06-04 08:57:22',0),(56,24,'Batrits',47,'Batrits同学，你在智能组卷002中获得47分（67.1%），答对8题，表现中规中矩。优势在于基础知识有一定掌握，能应对多数常规题型；但失分题暴露出概念理解或综合运用存在短板，得分率刚过及格线。建议你重点复盘错题，回归教材攻克薄弱章节，强化审题与检查习惯。每一次错误都是进步的阶梯，继续锤炼，必有突破！','2026-06-04 11:51:30','2026-06-04 11:52:15','已批阅',0,'2026-06-04 11:51:29','2026-06-04 11:51:29',0),(57,9,'hanli',53,'hanli同学，你在“测试001”中取得了53分（得分率58.9%），完成了基础知识的覆盖，说明你已具备一定的学习积累，尤其答对的10道题反映出你在部分知识点上掌握较为扎实，这是值得肯定的。\n\n不过，总分尚未达到及格线，暴露出知识体系存在较多薄弱环节，可能对概念理解不深、综合运用能力不足，或粗心导致失分。建议你首先将错题整理成册，逐题分析错误原因，回归课本或笔记巩固对应基础；其次，针对薄弱题型进行专项训练，注重审题和步骤规范；最后，定期自测，建立错题复习计划，避免同类错误重复出现。\n\n学习是一场长跑，一次的成绩只是路标，不是终点。你的潜力藏在尚未攻克的题目里，静下心、找对方法，你一定能稳步提升，期待你下次的突破！','2026-06-04 12:22:10','2026-06-04 12:23:38','已批阅',0,'2026-06-04 12:22:10','2026-06-04 12:22:10',0),(58,9,'hanli',58,'hanli同学，本次“测试001”你取得58分（64.4%），18题答对11题，说明基础知识有一定掌握，但整体表现距优秀仍有差距。你的优势在于已能解决约六成问题，学习态度值得肯定；不足之处是失分点较多，反映出部分概念理解不深、审题或解题熟练度不够。建议你接下来重点做好错题整理，针对薄弱知识点回归课本，逐个攻破，并通过限时练习提升准确率与速度。每一次扎实的复盘都是进步的阶梯，找准方向，稳扎稳打，下次一定能有明显突破，加油！','2026-06-04 12:35:01','2026-06-04 12:36:00','已批阅',0,'2026-06-04 12:35:01','2026-06-04 12:35:01',0),(59,9,'hanli',9,'Hanli同学，本次“测试001”的成绩显示，你在知识掌握上存在较大空缺，10%的得分率说明基础概念尚未建立牢固框架。仅答对1题也反映出你目前的学习方法或投入度需要及时调整。优势在于你仍有充足的时间去重构知识体系，不足则是知识漏洞多、解题技巧几乎空白。建议你暂停刷题，回归课本，从目录梳理每个单元的核心定义和公式，每日制定微小可执行的目标，并主动请教老师错题背后的逻辑。每一次低分都是重新出发的起点，只要踏实填补漏洞，进步会比想象中来得更快。别灰心，从今天的第一道错题开始，重建你的信心！','2026-06-04 12:37:20','2026-06-04 12:37:57','已批阅',0,'2026-06-04 12:37:20','2026-06-04 12:37:20',0),(60,24,'hanli',52,'hanli同学，本次智能组卷002考试总得分52分（满分70分），正确率74.3%，表现良好，说明你已经掌握了大部分核心知识，具备稳定的基础能力。  \n你的优势在于答对了9道题，基础题和中档题得分率较高，知识框架比较清晰。不足之处是仍有个别知识模块存在疏漏，遇到综合性强或略有变式的题目时，容易因细节疏忽或思路卡顿而失分。  \n建议后续加强错题归因整理，把薄弱知识点对应到具体题型反复打磨，同时适当练习审题圈画与过程检查，提升做题的准确度和稳定性。每次攻克一个小漏洞，都是在为更高分积蓄力量。保持住现在的学习节奏，稳扎稳打，你完全有能力向85%甚至更高的得分率迈进，继续加油！','2026-06-04 12:41:39','2026-06-04 12:42:21','已批阅',0,'2026-06-04 12:41:38','2026-06-04 12:41:38',0),(61,24,'hanli',52,'Hanli同学，这次智能组卷002的成绩总体良好，得分率74.3%，正确率75%，说明基础知识掌握比较扎实，能稳定发挥。你的优势在于多数题目思路清晰、答题准确率高。主要不足体现在个别知识点存在盲区，可能对综合性强或变式题目的迁移能力尚待加强。建议你把错题整理归类，深挖错因，针对性复习相关概念和题型；同时多做一点情境新颖的练习，训练审题与灵活运用。学习如登山，每一步踏实都在接近山顶，保持这份认真，继续精进，你会越来越出色！','2026-06-04 12:46:12','2026-06-04 12:48:16','已批阅',0,'2026-06-04 12:46:12','2026-06-04 12:46:12',0),(62,24,'hanli',48,'hanli同学，本次智能组卷002的考试总分70分，你取得了48分，得分率68.6%，答对了12道题中的8道。整体表现处于中等偏上水平，说明已具备一定的基础，但仍有明显的提升空间。\n\n你的优势在于能够正确完成大部分题目，展现出较好的知识掌握度和解题信心。不足之处是面对部分难题或易错点时，准确率还不够稳定，可能反映出知识网络的薄弱环节或审题、检查习惯上的欠缺。\n\n建议你重点做好以下改进：一是逐题复盘错题，深挖原因，是概念模糊、方法不当还是粗心，分类记录在错题本上；二是针对薄弱知识点进行专项练习，而不是泛泛刷题；三是养成边读题边圈画关键信息的习惯，完成后若时间允许务必回查。每次练习都当作正式考试，锤炼心态。68.6%是一个扎实的起点，找准问题，持续精进，你完全有能力冲上更高分段，加油！','2026-06-04 12:55:51','2026-06-04 12:56:40','已批阅',0,'2026-06-04 12:55:51','2026-06-04 12:55:51',0),(63,15,'hanli',0,'Hanli同学，本次“测试ai组卷”考试的成绩不太理想，总得分0分，这反映出当前阶段对所学知识点的掌握存在明显缺口，可能需要从基础环节重新梳理。不过，敢于面对不理想的成绩本身就是一种勇气，也让我们精准地找到了提升的起点。\n\n你的优势在于能够完整参与测试，这为后续针对性突破提供了清晰的参照。不足之处主要是核心概念理解不清、解题方法尚未内化，导致在四道题的考查中未能有效得分。\n\n建议从三方面改进：一是回归课本或课程资料，逐一排查错误题目涉及的知识点，用思维导图或错题本理清逻辑；二是从简单同类题入手，先模仿标准解题步骤，再逐步增加难度，建立信心；三是每周固定时间复习本周所学，通过自问自答检验掌握程度。学习是一场需要耐心的长跑，起步慢没关系，每一次查漏补缺都在为未来蓄力。请相信，扎实地补上这些短板后，你的进步一定会清晰可见。坚持下去，你能行！','2026-06-04 13:00:46','2026-06-04 13:00:53','已批阅',0,'2026-06-04 13:00:46','2026-06-04 13:00:46',0);
/*!40000 ALTER TABLE `exam_records` ENABLE KEYS */;

--
-- Table structure for table `notices`
--

DROP TABLE IF EXISTS `notices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notices` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '公告ID',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公告标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公告内容',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT 'NOTICE' COMMENT '公告类型：SYSTEM(系统)、FEATURE(新功能)、NOTICE(通知)',
  `priority` int DEFAULT '0' COMMENT '优先级：0-普通，1-重要，2-紧急',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否启用',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_deleted` tinyint DEFAULT '0' COMMENT '0-未删除，1-已删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_type` (`type`) USING BTREE,
  KEY `idx_priority` (`priority`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='公告表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `notices`
