/*!40000 ALTER TABLE `questions` DISABLE KEYS */;
INSERT INTO `questions` (`id`, `title`, `type`, `multi`, `category_id`, `difficulty`, `score`, `analysis`, `create_time`, `update_time`, `is_deleted`) VALUES (65,'测试选择题','CHOICE',0,13,'MEDIUM',5,'数据库的数据类型','2025-07-24 10:39:22','2025-07-27 04:38:02',1),(66,'测试判断题','JUDGE',0,14,'HARD',5,'java是世界上最好的语言','2025-07-25 09:14:14','2025-07-25 09:14:14',0),(67,'选择题1222','CHOICE',1,17,'HARD',5,'选择题解析','2025-07-27 03:16:13','2025-07-27 04:37:23',1),(68,'在 Redis 中，关于持久化方式 RDB 和 AOF 的描述，下列哪个选项是正确的？','CHOICE',0,19,'MEDIUM',5,'A 错误：RDB 默认是每隔一定时间（如900秒1次、300秒10次等）或条件触发，并非每秒同步；且 RDB 若发生故障会丢失最后一次快照后的所有数据。\n\nB 错误：AOF 默认是每秒同步（appendfsync everysec），但通常 AOF 性能比 RDB 略低，因为要频繁写入日志文件。\n\nC 正确：RDB 文件是二进制压缩的快照，加载速度一般比 AOF 的日志重放快。\n\nD 错误：同时开启时，Redis 重启会优先使用 AOF 文件恢复数据，因为 AOF 数据更完整。','2025-07-27 03:16:13','2026-05-19 13:42:19',0),(69,'简述什么是缓存穿透，并给出两种常见解决方案。','TEXT',0,24,'MEDIUM',5,'缓存穿透指查询不存在的数据，每次都越过缓存直达数据库，易造成数据库压力过大。\n\n布隆过滤器利用位图快速判断数据“一定不存在”，过滤大部分无效请求。\n\n缓存空对象将不存在的结果短暂缓存，避免重复查询数据库，但需配合过期时间与限流。','2025-07-27 03:16:13','2026-06-01 03:24:34',0),(70,'选择题999','CHOICE',1,30,'MEDIUM',5,'89999','2025-07-27 03:16:13','2025-07-27 04:40:29',1),(71,'选择题00000','CHOICE',1,18,'EASY',5,'测试','2025-07-27 09:23:32','2025-07-27 09:23:32',0),(72,'关于数据库事务的ACID特性，下列说法中正确的两项是','CHOICE',1,19,'MEDIUM',5,'选项 A（正确）：原子性（Atomicity）指事务是一个不可分割的工作单元，事务中的操作要么全部执行成功，要么全部不执行，不存在部分成功的情况。这是事务的基础特性之一。\n\n选项 B（正确）：一致性（Consistency）指事务执行前后，数据库必须保持完整性约束（如外键、唯一性、触发器等），从一个一致状态转变为另一个一致状态。如果事务违反一致性，整个事务会被回滚。\n\n选项 C（错误）：隔离性（Isolation）的目的是防止不同事务之间的相互干扰，而不是允许干扰。虽然某些隔离级别（如读未提交）可能允许脏读等干扰现象，但这属于权衡性能后的结果，隔离性的本质要求是事务之间应相互隔离，不能无控制地相互影响。\n\n选项 D（错误）：持久性（Durability）保证一旦事务提交，其对数据库的修改是永久性的，即使发生系统故障（如断电、崩溃），已提交的数据也不会丢失。数据库通过日志、备份等机制确保持久性，因此“可能因系统故障而丢失”的说法是错误的。','2025-07-27 10:28:56','2026-06-03 12:33:11',0),(73,'以下哪个是Spring框架的核心特性？','TEXT',0,24,'MEDIUM',5,'Spring框架的核心特性包括依赖注入、面向切面编程和事务管理等。','2025-07-28 09:28:42','2026-06-01 03:33:46',0),(74,'判断题哈哈','JUDGE',0,21,'MEDIUM',10,'答案正确的！','2025-07-28 09:28:42','2026-05-19 15:53:25',0),(75,'Spring框架中的依赖注入(DI)可以通过哪些方式实现？','CHOICE',1,17,'EASY',5,'Spring框架支持多种依赖注入方式，包括构造器注入、字段注入和Setter方法注入，这些都是常见的依赖注入方式。接口注入不是Spring框架中支持的依赖注入方式。','2025-07-29 08:51:12','2025-07-29 08:51:12',0),(76,'以下哪些注解用于Spring框架中声明Bean？','CHOICE',1,17,'EASY',5,'在Spring框架中，@Required、@Autowired和@Service注解都可以用来声明Bean。@Required注解用于指示必须注入一个bean，否则会抛出异常；@Autowired注解用于自动注入依赖；@Service注解用于标注服务层组件。@Qualifier注解用于指定注入的具体Bean，但本身不声明Bean。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(77,'Spring框架中的AOP（面向切面编程）支持哪些类型的切点表达式？','CHOICE',1,17,'EASY',5,'Spring框架中的AOP支持多种类型的切点表达式，包括execution表达式用于匹配方法执行，within表达式用于匹配指定类中的所有方法，this表达式用于匹配当前代理对象，以及bean表达式用于匹配特定名称的Bean。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(78,'Spring框架中的@Transactional注解默认支持哪些事务传播行为？','CHOICE',1,17,'EASY',5,'Spring框架中的@Transactional注解默认支持REQUIRED、SUPPORTS和MANDATORY三种事务传播行为。REQUIRED表示如果当前存在事务，则加入该事务；SUPPORTS表示如果当前存在事务，可以加入事务，否则以非事务方式执行；MANDATORY表示当前必须存在事务，否则抛出异常。NEVER表示当前方法不允许在事务中执行，与默认行为不同。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(79,'在Spring框架中，以下哪些注解可以用来声明组件？','CHOICE',1,17,'EASY',5,'在Spring框架中，@Component、@Service、@Repository和@Controller注解都可以用来声明组件。@Component注解用于泛指组件，@Service注解用于服务层组件，@Repository注解用于数据访问层组件，@Controller注解用于表现层组件。这些注解都可以使类成为Spring容器的Bean，从而被自动扫描和注册。','2025-07-29 08:51:13','2025-07-29 08:51:13',0),(81,'在 Spring Cloud 微服务架构中，使用 OpenFeign 进行声明式服务调用时，需要在启动类或配置类上添加哪个注解来开启 Feign 客户端功能？','CHOICE',0,18,'MEDIUM',5,'@EnableFeignClients 是 Spring Cloud OpenFeign 提供的核心注解，用于扫描并注册声明了 @FeignClient 的接口，从而生成代理对象实现服务调用。通常加在 Spring Boot 启动类或配置类上。\n\n@FeignClient 用于定义具体的 Feign 客户端接口，并非开启功能的注解。\n\n@EnableFeign 和 @EnableFeignClient 不是 Spring Cloud 中的标准注解，容易混淆但无效。','2026-05-19 11:51:39','2026-05-19 11:51:39',0),(82,'关于 Git 的工作流程和常用命令，下列说法中正确的有（多选）','CHOICE',1,30,'MEDIUM',5,'A 正确：git add . 会将当前目录下的所有变更（包括新增、修改、删除）添加到暂存区。注意与 git add -A 作用相同（Git 2.0+），但 git add . 在根目录下也会包括删除操作。\n\nB 正确：git commit 基于暂存区创建快照，提交后工作区保持不变，已跟踪但未暂存的文件不会包含在本次提交中。\n\nC 错误：git push origin master 只推送当前分支到远程 master 分支，但不会自动建立追踪关系（除非使用 -u 参数）。\n\nD 正确：git fetch 只下载远程更新但不合并，git pull = git fetch + git merge（默认行为）。\n\nE 错误：git branch -d 只能删除已合并的分支，若要强制删除未合并的分支应使用 git branch -D（大写 D）。','2026-05-19 11:55:11','2026-05-19 11:55:11',0),(83,'关于 Java 中静态方法对实例变量（非静态变量）的访问，下列说法正确的是？','CHOICE',0,21,'MEDIUM',5,'静态方法属于类本身，在调用时不需要创建类的实例；而实例变量（非静态变量）属于对象，必须通过对象引用才能访问。因此，静态方法中不能直接访问实例变量，只能访问静态变量或通过创建对象后使用对象引用访问实例变量。\n\n','2026-05-19 11:59:22','2026-05-19 15:51:25',1),(84,'以下哪个是Java的基本数据类型？','CHOICE',0,1,'EASY',2,'int是Java的8种基本数据类型之一','2026-05-24 07:49:04','2026-05-24 07:49:04',0),(85,'在Java中，子类可以继承父类的构造方法','JUDGE',0,21,'EASY',3,'构造方法不能被继承。子类必须通过 super() 显式或隐式调用父类的构造方法\n','2026-05-24 07:58:17','2026-05-24 07:58:17',0),(86,'以下哪个是Java的双列集合？','CHOICE',0,1,'EASY',2,'int是Java的8种基本数据类型之一','2026-05-24 12:21:28','2026-05-24 12:21:28',0),(87,'在 Java 中，如果一个类没有定义任何构造方法，编译器会自动生成一个无参构造方法；但如果这个类的父类只有带参构造方法且没有无参构造方法，编译器会报错。','JUDGE',0,21,'EASY',3,'子类构造器默认会调用父类的无参构造器 super()。\n\n若父类只定义了带参构造器，则不再有无参构造器。\n\n此时编译器无法自动生成调用，子类必须用 super(参数) 显式调用父类带参构造器，否则编译报错。\n','2026-05-24 12:21:28','2026-05-24 12:21:28',0),(88,'在Maven项目中，希望跳过单元测试的执行但仍编译测试代码，应使用哪个命令参数？','CHOICE',0,29,'MEDIUM',5,'-DskipTests 会跳过测试执行但依然编译测试类；-Dmaven.test.skip=true 会同时跳过测试编译和执行；其他选项不是有效的Maven参数。','2026-05-25 13:52:00','2026-05-25 13:52:00',0),(89,'在多模块Maven项目中，构建模块A时，还想自动构建模块A所依赖的其他模块，应使用哪个命令？','CHOICE',0,29,'MEDIUM',5,'-pl (--projects) 指定要构建的模块，-am (--also-make) 同时构建指定模块所依赖的模块；-amd (--also-make-dependents) 则构建依赖于指定模块的模块；选项D的参数顺序错误，-am 后面不应直接跟模块名。','2026-05-25 13:52:00','2026-05-25 13:52:00',0),(90,'执行命令 mvn -U clean package 时，参数 -U 的作用是什么？','CHOICE',0,29,'MEDIUM',5,'-U (--update-snapshots) 强制检查并更新远程仓库中的SNAPSHOT依赖和插件，不会强制更新release版本；离线模式使用 -o；跳过测试使用 -DskipTests。','2026-05-25 13:52:00','2026-05-25 13:52:00',0),(91,'想要查看Maven项目合并了所有settings.xml和父POM后的实际生效配置（setting部分），应使用哪个命令？','CHOICE',0,29,'MEDIUM',5,'help:effective-settings 显示合并用户 settings.xml 和全局 settings.xml 后的实际配置；help:effective-pom 显示项目合并后的完整POM；help:active-profiles 列出当前激活的profile；help:system 显示系统属性和环境变量。','2026-05-25 13:52:00','2026-05-25 13:52:00',0),(92,'命令 mvn dependency:tree -Dverbose=true 的输出包含什么关键信息？','CHOICE',0,29,'MEDIUM',5,'dependency:tree 显示项目依赖树，-Dverbose 参数会显示更详细的信息，包括冲突的依赖被忽略的版本、重复依赖等；图形化报告需要使用其他参数或插件；该命令不会自动解决冲突。','2026-05-25 13:52:00','2026-05-25 13:52:00',0),(93,'在Java中，synchronized关键字实现的锁是可重入锁，即一个线程在获得某个对象的锁之后，可以再次获取该对象的锁而不会被阻塞。','JUDGE',0,21,'MEDIUM',5,'Java中的synchronized锁是可重入锁（ReentrantLock特性之一）。每个对象头中维护了持有锁的线程ID和重入次数，当同一个线程再次请求该锁时，重入次数加1，不会被阻塞。这是Java内置锁的基本特性，防止线程自己阻塞自己。','2026-05-25 13:57:12','2026-05-25 13:57:12',0),(94,'ReentrantLock的公平锁模式保证先等待的线程一定先获得锁，因此其性能总是优于非公平锁。','JUDGE',0,21,'MEDIUM',5,'ReentrantLock的公平锁通过严格的队列顺序保证先等待的线程先获得锁，但需要额外的线程调度和上下文切换开销，吞吐量低于非公平锁。非公平锁在释放锁时允许插队，减少上下文切换，通常性能更高。因此公平锁并不总是优于非公平锁，在大多数并发场景下非公平锁吞吐量更高。','2026-05-25 13:57:13','2026-05-25 13:57:13',0);
